        /**
          * Accessible name for the dialog.
          * @default 'Command palette'
         */
        "label"?: string;
        /**
          * Fires whenever the palette opens or closes, whoever caused it.
         */
        "onPfOpenChange"?: (event: PfCommandPaletteCustomEvent<{ open: boolean }>) => void;
